/* ================= v2.5.61-flash 79 轮黑匣子（纯 ES5，先于主块装载） =================
   用户证词实锤：任何历史版本从未在真机跑通过 -> 主块整块语法死时连一句日志都写不出来。
   本块语法比主块低两个世代，s0 旗标先落盘——Java 看门狗 6s 后读 bootLog：
   空=黑匣子也没跑（装载层死）；只有 s0=主块装载期语法死（一目了然）。 */
(function(){
  function _bb(k,v){try{window.DSB&&DSB.storeSet(k,JSON.stringify(v))}catch(e){}}
  function _bl(s){try{window.__bl=window.__bl||[];window.__bl.push(s);_bb("bootLog",{steps:window.__bl,t:Date.now()})}catch(e){}}
  window.bLog=_bl;
  _bl("s0-blackbox-ready");
  window.addEventListener("error",function(ev){_bb("bootFailLog",{m:String((ev&&ev.error&&ev.error.stack)||(ev&&ev.message)||"unknown"),ua:navigator.userAgent,t:Date.now()})},true);
  window.addEventListener("unhandledrejection",function(ev){_bb("bootFailLog",{m:"unhandledrejection:"+((ev&&ev.reason)?String(ev.reason.stack||ev.reason).slice(0,300):"?"),ua:navigator.userAgent,t:Date.now()})});
})();
</script>
