  function def(o,k,f){try{if(!(k in o))o[k]=f}catch(e){}}
  def(Object,"assign",function(t){if(t===null||t===undefined)throw new TypeError("assign null");t=Object(t);for(var i=1;i<arguments.length;i++){var s=arguments[i];if(s===null||s===undefined)continue;var ks=Object.keys(s);for(var j=0;j<ks.length;j++){t[ks[j]]=s[ks[j]]}}return t});
  def(Object,"values",function(o){var r=[];if(o===null||o===undefined)return r;var ks=Object.keys(o);for(var i=0;i<ks.length;i++)r.push(o[ks[i]]);return r});
  def(Object,"entries",function(o){var r=[];if(o===null||o===undefined)return r;var ks=Object.keys(o);for(var i=0;i<ks.length;i++)r.push([ks[i],o[ks[i]]]);return r});
  def(Array.prototype,"includes",function(x){for(var i=0;i<this.length;i++){if(this[i]===x||(x!==x&&this[i]!==this[i]))return true}return false});
  def(Array.prototype,"find",function(f){for(var i=0;i<this.length;i++){if(f(this[i],i,this))return this[i]}});
  def(String.prototype,"includes",function(x){return this.indexOf(String(x))!==-1});
  def(String.prototype,"startsWith",function(x,p){p=p||0;return this.slice(p,p+String(x).length)===String(x)});
  def(String.prototype,"endsWith",function(x,p){var s=String(this);x=String(x);p=(p===undefined||p>s.length)?s.length:p;var d=p-x.length;return d>=0&&s.slice(d,p)===x});
  def(String.prototype,"padStart",function(n,f){var s=String(this);n=n>>0;f=(f===undefined?" ":String(f));if(s.length>=n)return s;var r="";var need=n-s.length;while(r.length<need)r+=f;r=r.slice(0,need);return r+s});
  def(String.prototype,"padEnd",function(n,f){var s=String(this);n=n>>0;f=(f===undefined?" ":String(f));if(s.length>=n)return s;var r="";var need=n-s.length;while(r.length<need)r+=f;r=r.slice(0,need);return s+r});
